        # models the re-dispatched run appearing only after the cancel.
        if ls "\$GH_STUB_DIR"/cancelled-* >/dev/null 2>&1 && [ -f "\$GH_STUB_DIR/runs2.json" ]; then
          runs_file="\$GH_STUB_DIR/runs2.json"
        fi
        if [ "\$calls" -le "\${GH_STUB_LIST_EMPTY_FIRST:-0}" ]; then
          printf '[]' | apply_jq
        else
          cat "\$runs_file" | apply_jq
        fi
        ;;
      view)
        id="\$3"
        # `--json jobs` polls (gh-172 queue-stall guard) are served from
        # jobs-<id>.txt: one running-job COUNT per poll, last line repeats;
        # absent file = 1 job running (healthy child) so older fixtures
        # without job modeling keep their behavior. cancelled = 0.
